typedef unsigned int nslSoundId;
#define NSL_INVALID_ID 0

void mem_lock_malloc(bool);
void nglReleaseAllTextures();

class GenericGameSaver {
public:
  static GenericGameSaver *instance;
  static GenericGameSaver *inst() { return instance; }
  void releaseIconData();
};

class game { char pad[652]; public: int start_drawing_map; };
class entity_maker { public: void purge_entity_cache(); };
class world_dynamics_system { public: void unload_scene(); };
extern game *g_game_ptr;
extern entity_maker *g_entity_maker;
extern world_dynamics_system *g_world_ptr;
extern nslSoundId feMusic;

class GraphicalMenuSystem { public: virtual ~GraphicalMenuSystem(); };
class FEEntityManager { public: virtual ~FEEntityManager(); };
class IGOFrontEnd;
class PauseMenuSystem;
class LegalFrontEnd;
class TitleFrontEnd;

class entity_anim { public: static void mem_cleanup(); };
class entity_anim_tree { public: static void mem_cleanup(); };
class po_anim { public: static void mem_cleanup(); };
class quaternion;
class vector3d;
typedef float rational_t;
template<class T> class linear_anim { public: static void mem_cleanup(); };
class entity { public: class movement_info { public: static void mem_cleanup(); }; };
class app { public: static void cleanup_stl_memory_dregs(); };

class entity_manager {
public:
  static entity_manager *instance;
  static entity_manager *inst() { return instance; }
  void purge();
};
class hw_texture_mgr {
public:
  static hw_texture_mgr *instance;
  static hw_texture_mgr *inst() { return instance; }
  void unload_all_textures();
};
class slc_manager {
public:
  static slc_manager *instance;
  static slc_manager *inst() { return instance; }
  void purge();
};

class vr_pmesh;
class cg_mesh;
class vr_billboard;
class material;
template<class T> class instance_bank { public: void purge(); void debug_dump(); };
extern instance_bank<vr_pmesh> vr_pmesh_bank;
extern instance_bank<cg_mesh> cg_mesh_bank;
extern instance_bank<vr_billboard> vr_billboard_bank;
extern instance_bank<material> material_bank;

class FEManager {
public:
  IGOFrontEnd* IGO;
  PauseMenuSystem* pms;
  GraphicalMenuSystem* gms;
  FEEntityManager* em;
  LegalFrontEnd* lfe;
  TitleFrontEnd* tfe;
  char released_layout[0x15678 - 24];
  int fe_done;
  int fe_done_loading;
  void ReleaseFE();
};

void FEManager::ReleaseFE()
{
  mem_lock_malloc(false);
  GenericGameSaver::inst()->releaseIconData();
  g_game_ptr->start_drawing_map = false;
  g_entity_maker->purge_entity_cache();
  g_world_ptr->unload_scene();
  feMusic = NSL_INVALID_ID;
  delete gms;
  gms = 0;
  lfe = 0;
  tfe = 0;
  delete em;
  em = 0;
  entity_anim::mem_cleanup();
  entity_anim_tree::mem_cleanup();
  po_anim::mem_cleanup();
  linear_anim<quaternion>::mem_cleanup();
  linear_anim<vector3d>::mem_cleanup();
  linear_anim<rational_t>::mem_cleanup();
  entity::movement_info::mem_cleanup();
  app::cleanup_stl_memory_dregs();
  entity_manager::inst()->purge();
  vr_pmesh_bank.purge();
  vr_pmesh_bank.debug_dump();
  hw_texture_mgr::inst()->unload_all_textures();
  slc_manager::inst()->purge();
  cg_mesh_bank.purge();
  vr_billboard_bank.purge();
  vr_pmesh_bank.purge();
  material_bank.purge();
  nglReleaseAllTextures();
  fe_done = true;
  fe_done_loading = false;
}
